actor SocketClient {
    private var task: URLSessionWebSocketTask?

    func connect(_ url: URL) -> AsyncThrowingStream<Data, Error> {
        let task = URLSession.shared.webSocketTask(with: url)
        self.task = task
        task.resume()
        return AsyncThrowingStream { continuation in
            let reader = Task {
                do {
                    while !Task.isCancelled {
                        switch try await task.receive() {
                        case .data(let d): continuation.yield(d)
                        case .string(let s): continuation.yield(Data(s.utf8))
                        @unknown default: break
                        }
                    }
                } catch { continuation.finish(throwing: error) }   // caller reconnects with backoff
            }
            continuation.onTermination = { _ in reader.cancel(); task.cancel(with: .goingAway, reason: nil) }
        }
    }
}
